#!/usr/bin/env python3
from __future__ import annotations

import argparse
import ast
import json
import subprocess
from pathlib import Path
from typing import Any

ROOT_DIR = Path(__file__).resolve().parents[2]
GENERATED_MARKERS = (
    "Code generated",
    "DO NOT EDIT",
    "AUTOGENERATED",
    "This file is generated",
)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description=(
            "Report candidate pass-through constant aliases across Go, Python, "
            "and TypeScript."
        )
    )
    parser.add_argument(
        "--language",
        action="append",
        choices=("go", "python", "typescript"),
        help="Limit results to one or more languages.",
    )
    parser.add_argument(
        "--format",
        choices=("text", "json"),
        default="text",
        help="Output format.",
    )
    parser.add_argument(
        "--limit",
        type=int,
        default=200,
        help="Maximum number of candidates to print.",
    )
    parser.add_argument(
        "--path-contains",
        help="Keep only candidates whose path contains this text.",
    )
    parser.add_argument(
        "--name-contains",
        help="Keep only candidates whose constant name contains this text.",
    )
    parser.add_argument(
        "--rhs-contains",
        help="Keep only candidates whose aliased expression contains this text.",
    )
    parser.add_argument(
        "--include-generated",
        action="store_true",
        help="Include generated files. Generated files are excluded by default.",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    selected_languages = set(args.language or ("go", "python", "typescript"))
    candidates: list[dict[str, Any]] = []

    if "python" in selected_languages:
        candidates.extend(scan_python_candidates(args.include_generated))
    if "go" in selected_languages:
        candidates.extend(
            run_helper(
                [
                    "./scripts/go.sh",
                    "run",
                    "./scripts/pass_through_constant_aliases/go_candidates.go",
                    "--root",
                    str(ROOT_DIR),
                    *generated_flag(args.include_generated),
                ]
            )
        )
    if "typescript" in selected_languages:
        candidates.extend(
            run_helper(
                [
                    "node",
                    "./scripts/pass_through_constant_aliases/ts_candidates.mjs",
                    "--root",
                    str(ROOT_DIR),
                    *generated_flag(args.include_generated),
                ]
            )
        )

    filtered = [
        candidate
        for candidate in candidates
        if matches_contains(candidate.get("path"), args.path_contains)
        and matches_contains(candidate.get("name"), args.name_contains)
        and matches_contains(candidate.get("rhs"), args.rhs_contains)
    ]
    filtered.sort(
        key=lambda candidate: (
            str(candidate.get("language", "")),
            str(candidate.get("path", "")),
            int(candidate.get("line", 0)),
            int(candidate.get("column", 0)),
            str(candidate.get("name", "")),
        )
    )

    limited = filtered[: max(args.limit, 0)]
    if args.format == "json":
        print(
            json.dumps(
                {
                    "matched": len(filtered),
                    "returned": len(limited),
                    "candidates": limited,
                },
                indent=2,
            )
        )
        return 0

    print(f"matched: {len(filtered)} returned: {len(limited)}")
    for candidate in limited:
        location = f"{candidate['path']}:{candidate['line']}"
        if candidate.get("column"):
            location += f":{candidate['column']}"
        print(
            " | ".join(
                [
                    str(candidate.get("language", "-")),
                    location,
                    str(candidate.get("scope", "-")),
                    str(candidate.get("name", "-")),
                    str(candidate.get("rhs", "-")),
                ]
            )
        )
    return 0


def generated_flag(include_generated: bool) -> list[str]:
    if include_generated:
        return ["--include-generated"]
    return []


def run_helper(command: list[str]) -> list[dict[str, Any]]:
    result = subprocess.run(
        command,
        cwd=ROOT_DIR,
        capture_output=True,
        text=True,
        check=True,
    )
    payload = json.loads(result.stdout or "[]")
    if not isinstance(payload, list):
        raise ValueError(f"Expected helper list payload, got: {type(payload)!r}")
    return [candidate for candidate in payload if isinstance(candidate, dict)]


def matches_contains(value: Any, needle: str | None) -> bool:
    if needle is None:
        return True
    return needle.lower() in str(value or "").lower()


def scan_python_candidates(include_generated: bool) -> list[dict[str, Any]]:
    candidates: list[dict[str, Any]] = []
    for relative_path in tracked_files():
        if not relative_path.endswith(".py"):
            continue
        if not include_generated and is_generated_file(relative_path):
            continue
        file_path = ROOT_DIR / relative_path
        source = file_path.read_text(encoding="utf-8")
        tree = ast.parse(source, filename=str(file_path))
        candidates.extend(
            scan_python_body(
                body=tree.body,
                relative_path=relative_path,
                scope="module",
            )
        )
    return candidates


def scan_python_body(
    body: list[ast.stmt],
    relative_path: str,
    scope: str,
) -> list[dict[str, Any]]:
    candidates: list[dict[str, Any]] = []
    for statement in body:
        if isinstance(statement, ast.ClassDef):
            candidates.extend(
                scan_python_body(
                    body=statement.body,
                    relative_path=relative_path,
                    scope=f"class {statement.name}",
                )
            )
            continue

        name = ""
        value_node: ast.expr | None = None
        if isinstance(statement, ast.Assign):
            if len(statement.targets) != 1:
                continue
            target = statement.targets[0]
            if not isinstance(target, ast.Name):
                continue
            name = target.id
            value_node = statement.value
            line = statement.lineno
            column = target.col_offset + 1
        elif isinstance(statement, ast.AnnAssign):
            if not isinstance(statement.target, ast.Name) or statement.value is None:
                continue
            name = statement.target.id
            value_node = statement.value
            line = statement.lineno
            column = statement.target.col_offset + 1
        else:
            continue

        if not is_python_constant_name(name):
            continue
        rhs = python_simple_alias_expr(value_node)
        if rhs is None:
            continue
        candidates.append(
            {
                "language": "python",
                "path": relative_path,
                "line": line,
                "column": column,
                "scope": scope,
                "name": name,
                "rhs": rhs,
                "kind": "python-constant-assignment",
            }
        )
    return candidates


def python_simple_alias_expr(node: ast.expr) -> str | None:
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        base = python_simple_alias_expr(node.value)
        if base is None:
            return None
        return f"{base}.{node.attr}"
    return None


def is_python_constant_name(name: str) -> bool:
    if not name:
        return False
    if name.startswith("__") and name.endswith("__"):
        return False
    return name.replace("_", "").isalnum() and name.upper() == name


def tracked_files() -> list[str]:
    result = subprocess.run(
        ["git", "-C", str(ROOT_DIR), "ls-files", "-z"],
        capture_output=True,
        check=True,
    )
    return [path.decode("utf-8") for path in result.stdout.split(b"\0") if path]


def is_generated_file(relative_path: str) -> bool:
    normalized = relative_path.replace("\\", "/")
    if "/generated/" in f"/{normalized}/":
        return True
    if normalized.startswith("frontend/generation/"):
        return True
    header = (ROOT_DIR / relative_path).read_text(encoding="utf-8")[:512]
    return any(marker in header for marker in GENERATED_MARKERS)


if __name__ == "__main__":
    raise SystemExit(main())
